function sortArray(A):
    n = length(A)

    for i from 0 to n-2:
        minIndex = i

        for j from i+1 to n-1:
            if A[j] < A[minIndex]:
                minIndex = j

        if minIndex != i:
            swap(A[i], A[minIndex])

    return A

function swap(x, y):
    temp = x
    x = y
    y = temp

